from pathlib import Path
import html, json, shutil, re
from xml.etree import ElementTree as ET

ROOT = Path(__file__).parent
OUT = ROOT / 'dist'
ORIGIN = 'https://alvento.uk/nullkey'
PRIVACY = 'https://alvento.uk/nullkey/privacy/'
GA4 = '<script async src="https://www.googletagmanager.com/gtag/js?id=G-N94LC333HG"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag("js",new Date());gtag("consent","default",{analytics_storage:(function(){try{return localStorage.getItem("alvento_consent")==="granted"?"granted":"denied";}catch(e){return "denied";}})()});gtag("config","G-N94LC333HG");</script>'
CONTACT = 'mailto:hello@alvento.uk?subject=NullKey%20testing'
release = json.loads((ROOT / 'content/release.json').read_text())
# Only generated output is replaced. Legal and brand review drafts remain in source.
if OUT.exists(): shutil.rmtree(OUT)
OUT.mkdir()
for source in (ROOT / 'assets').iterdir():
    if source.is_dir(): shutil.copytree(source, OUT / source.name)
    else: shutil.copyfile(source, OUT / source.name)

def esc(value): return html.escape(str(value), quote=True)
def a(url, text, cls=''): return f'<a href="{esc(url)}" class="{cls}">{text}</a>'
def nav(route):
    links = ''.join(a('https://alvento.uk'+url,label) for url,label in [('/#capabilities','Capabilities'),('/#lab','Products'),('/tools/','Tools'),('/case-studies/','Case studies'),('/blog/','Insights')])+a('https://alvento.uk/#contact','Discuss your project','button compact')
    product_links = ''.join(a(url,label, 'active' if route==url else '') for url,label in [('/#how-it-works','Overview'),('/security/','Security'),('/guides/','Guides'),('/availability/','Testing & availability')])
    return '<a class="skip" href="#main">Skip to content</a><header class="alvento-header"><div class="wrap alvento-header-inner">'+a('https://alvento.uk/','alvento<span>.</span>','alvento-logo')+'<nav class="desktop-nav" aria-label="Alvento navigation">'+links+'</nav><details class="mobile-nav"><summary>Menu</summary><nav aria-label="Mobile navigation">'+links+'</nav></details></div></header><div class="wrap product-bar">'+a('/','<img src="/mark.svg" width="28" height="28" alt="">NullKey <span>An Alvento product</span>','product-identity')+'<nav aria-label="NullKey navigation">'+product_links+'</nav></div>'
footer = '<footer class="alvento-footer"><div class="wrap"><div class="footer-top"><div>'+a('https://alvento.uk/','alvento<span>.</span>','alvento-logo')+'<p>NullKey. An Alvento product.</p></div><nav aria-label="Footer navigation">'+''.join(a(url,label) for url,label in [('/availability/','NullKey availability'),('/security/','Security'),(PRIVACY,'App privacy policy'),('/about/','Product support'),('https://alvento.uk/case-studies/','More from Alvento'),('https://alvento.uk/privacy/','Website privacy')])+'</nav></div><div class="footer-bottom"><span>© 2026 Alvento Ltd. Company No. 16394298. United Kingdom.</span>'+a('https://alvento.uk/','alvento.uk')+'</div></div></footer>'
routes = []
def page(route, title, description, body):
    routes.append(route)
    target = OUT / route.strip('/') / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    url = ORIGIN + route
    document = f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} | NullKey by Alvento</title><meta name="description" content="{esc(description)}"><meta name="robots" content="index,follow"><link rel="canonical" href="{url}"><meta name="theme-color" content="#090a06"><meta property="og:title" content="{esc(title)} | NullKey"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/feature-graphic.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="/mark.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&amp;family=DM+Sans:wght@400;500;600;700&amp;family=JetBrains+Mono:wght@400;500&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="/style.css"><script src="/site.js" defer></script></head><body>{nav(route)}<main id="main" tabindex="-1" class="wrap">{body}</main>{footer}</body></html>'''
    document = re.sub(r'(href|src)="/(?!/)', r'\1="/nullkey/', document)
    # Site-wide GA4 + consent banner, added after the /nullkey/ path rewrite so the root script path survives.
    document = document.replace('</head>', GA4 + '</head>', 1).replace('</body>', '<script defer src="/consent-banner.js"></script></body>', 1)
    target.write_text(document)
def head(label,title,intro): return f'<div class="page-head"><span class="eyebrow">{label}</span><h1>{title}</h1><p class="lead">{intro}</p></div>'
def article(title,intro,sections,label='NullKey / explained'):
    body=''.join(f'<section id="section-{i}"><h2>{h}</h2>{p}</section>' for i,(h,p) in enumerate(sections))
    toc='<aside class="contents" aria-label="On this page"><strong>On this page</strong>'+''.join(a(f'#section-{i}',h) for i,(h,p) in enumerate(sections))+'</aside>'
    return head(label,title,intro)+f'<div class="article-layout"><article>{body}</article>{toc}</div>'
def faq(q,answer): return f'<details><summary>{q}</summary><p>{answer}</p></details>'
def guides_cards(items): return ''.join(f'<a class="guide" href="/guides/{slug}/"><span class="eyebrow">Practical guide</span><h3>{esc(title)}</h3><p>{esc(desc)}</p><span class="read">Read guide</span></a>' for slug,title,desc,_ in items)

guides=json.loads((ROOT/'content/guides.json').read_text())
# Actual product screens are copied from the app's approved synthetic-data captures.
shots=json.loads((ROOT/'content/screenshots.json').read_text())
hero_image = f'<img class="app-screen" src="/screenshots/{shots[0][0]}" width="{shots[0][3]}" height="{shots[0][4]}" alt="{esc(shots[0][2])}" fetchpriority="high">'
hero=f'''<section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="status-dot"></span> Offline vault / Android</span><h1>Your files.<br>Your keys.<br><em>Not ours.</em></h1><p class="lead">Keep private photos, files and notes in an encrypted vault on your phone. No account. No ads. No developer server.</p><div class="actions">{a('/availability/','Try NullKey','button')}{a('#how-it-works','See how it works','text-link')}</div><p class="status">Google Play internal testing · Android 11+</p></div><figure class="hero-product"><div class="product-label"><span>NULLKEY / ON YOUR DEVICE</span><img src="/mark.svg" width="29" height="29" alt=""></div>{hero_image}<figcaption>Real app interface · Sample data</figcaption></figure></section>'''
features='''<div class="trust-strip"><span>Encrypted on your phone</span><span>No account to create</span><span>You hold the recovery key</span></div>
<section class="section" id="how-it-works"><div class="section-heading"><span class="eyebrow">A place for your private things</span><h2>A small routine.<br>A little more privacy.</h2></div><div class="steps"><div><span class="number">01</span><h3>Make it yours.</h3><p>Create a vault with a passphrase. Save your recovery key somewhere separate from your phone.</p></div><div><span class="number">02</span><h3>Bring your files in.</h3><p>Import photos and files with Android’s picker, or write a private note. Search names inside your unlocked vault.</p></div><div><span class="number">03</span><h3>Keep a way back.</h3><p>Create and verify an encrypted backup. Keep a separate copy and the secret that unlocks it.</p></div></div><p class="note">Importing keeps originals by default. <a href="/guides/before-deleting-originals/">Understand your copies before deleting anything.</a></p></section>'''
gallery='<section class="section"><div class="section-heading"><span class="eyebrow">Inside NullKey</span><h2>Private things.<br>One familiar place.</h2><p class="lead">Photos, documents and notes, with the same simple routine.</p></div><div class="screen-gallery">'+''.join(f'<figure><img src="/screenshots/{filename}" width="{width}" height="{height}" alt="{esc(alt)}" loading="lazy"><figcaption><strong>{esc(label)}</strong></figcaption></figure>' for filename,label,alt,width,height in shots[1:])+'</div><p class="note">'+esc(release['screenshot_note'])+'</p></section>'
security_home='''<section class="section split"><div><span class="eyebrow">Private from us, too</span><h2>We don’t keep<br>a spare key.</h2><p class="lead">Your passphrase and recovery key unlock your vault. Alvento receives neither your vault contents nor its decryption keys.</p><a class="text-link" href="/security/">Read the security model</a></div><div class="detail-list"><div><h3>Local encryption.</h3><p>AES-256-GCM protects stored contents. Argon2id derives a key from your passphrase. The current app has no internet permission.</p></div><div><h3>Your choice of unlock.</h3><p>Use your passphrase, or enable supported biometric, phone screen-lock or in-app pattern unlock. A pattern is a convenience, with weaker protection.</p></div><div><h3>A backup you can check.</h3><p>NullKey checks the exported archive, encrypted items and thumbnails against your vault. Restore into an empty vault with the backup’s passphrase or recovery key.</p></div></div></section>'''
pricing='''<section class="section pricing" id="pricing"><div><span class="eyebrow">A clear starting point</span><h2>Free during<br>this first release.</h2><p class="lead">The current build has no paid unlock and no item cap.</p></div><div><h3>A one-time unlock is planned.</h3><p>A later update will introduce a 30-item free allowance across photos, files and notes, with a one-time purchase to add more. No subscription is planned for that release.</p><p>Existing items, editing, export, backup and restore will remain free. That limit is <strong>not active in today’s build</strong>.</p><a href="/availability/#pricing">Read the release and pricing plan</a></div></section>'''
faqs=faq('Can I download NullKey now?','NullKey is available to invited testers through Google Play internal testing. A public release has not launched. <a href="/availability/">Check availability or ask about testing.</a>')+faq('Can Alvento read my private files?','The app sends no vault contents or decryption keys to Alvento. Your phone decrypts them when you unlock. A compromised or unlocked phone remains a risk.')+faq('What if I forget my passphrase?','A saved recovery key can open an existing vault. If the phone or files are gone, you also need a backup. Losing both secrets means we cannot reset your access.')+faq('Does importing delete the originals?','No, not by default. Optional original removal checks eligible local files first. Android asks before supported photos and videos go to trash; other supported documents may be deleted permanently. Other copies can remain.')+faq('Which phones does it work on?','NullKey requires Android 11 or later. Biometric and hardware-backed unlock options depend on the device. The app has no in-app video or PDF viewer; readable exports open outside the vault’s protection.')+faq('Has it had an independent security audit?','No. The app has internal reviews and automated tests, but those are not an independent audit. Keep separate, tested backups of irreplaceable files.')
closing='<section class="closing"><img src="/mark.svg" width="60" height="60" alt=""><h2>Your files belong to you.</h2><p>Start with sample files. Keep a backup. Make privacy a habit.</p>'+a('/availability/','Check testing availability','button')+'</section>'
page('/','Private photos, files & notes. Offline.','NullKey is an offline encrypted vault for Android. No account, no ads, and no developer server. Now in Google Play internal testing.',hero+features+gallery+security_home+pricing+'<section class="section split"><div><span class="eyebrow">Before you start</span><h2>Straight answers.</h2></div><div class="faq">'+faqs+'</div></section><section class="section"><div class="section-heading"><span class="eyebrow">Practical privacy</span><h2>Know what you’re keeping.</h2></div><div class="guide-grid">'+guides_cards([guides[2],guides[3],guides[4]])+'</div></section>'+closing)

availability=head('Availability / Android','Testing now.<br>Public release ahead.','NullKey is in Google Play internal testing. Access is limited to invited testers while we prepare the public release.')+f'''<div class="release-band"><span class="status-dot"></span><strong>{esc(release['version'])} · Internal testing</strong><span>Updated {esc(release['checked_date'])}</span></div><div class="availability-grid"><section><span class="eyebrow">For prospective testers</span><h2>Ask about access.</h2><p>Email us if you’d like to try NullKey. We’ll confirm whether testing places are available and send the appropriate instructions. An enquiry does not automatically enrol you.</p>{a(CONTACT,'Ask about testing','button')}<p class="note">Opens your email app. Please don’t send private files, backups, passphrases or recovery keys.</p></section><section><span class="eyebrow">Already invited?</span><h2>Use your invitation.</h2><p>Open the Play testing link you received while signed into the Google account invited to the test. Internal testing access is separate from a public Play listing.</p><p>Android 11 or later is required. Start with sample files and check backup and restore before relying on the app.</p></section></div><section class="section" id="pricing"><span class="eyebrow">Release and pricing plan</span><h2>Free now. A one-time unlock later.</h2><p>The current {esc(release['version'])} build has no billing and no item cap. A later release will introduce a 30-item free allowance across photos, files and notes, and a one-time purchase to add more.</p><p>Existing items, editing, export, backup and restore will remain free, including access to a vault already above 30 items. No subscription is planned for that release. Final purchase pricing will be shown before you buy.</p><p>Public release timing has not been announced. This page will link to the public Google Play listing when it is available.</p></section><section class="section"><h2>Moving from an earlier test build?</h2><p>If you used the earlier sideloaded app with package name <code>uk.alvento.cellar</code>, the current <code>uk.alvento.nullkey</code> is a separate app. Installing it does not transfer your vault.</p><ol><li>Create and verify an encrypted backup in the old app.</li><li>Keep the passphrase or recovery key for that backup separately.</li><li>Restore into an empty NullKey vault and check the contents.</li><li>Only then consider removing the old app. Keep your independent backup.</li></ol><p><strong>Do not uninstall or clear the old app before verifying the restored copy.</strong></p></section>'''
page('/availability/','Android testing & availability','NullKey 0.4.2 is in Google Play internal testing. Learn how to enquire about access, what is free now and what is planned for a later release.',availability)

security=[
('Who holds the keys','<p>Your phone creates and uses the vault’s keys. Alvento does not receive your vault contents, passphrase, recovery key or decryption keys. There is no account reset or provider-held copy of your vault.</p><p>“Your keys” here describes key custody, not a claim to hide every trace of a file. While unlocked, Android and the app process readable data.</p>'),
('How encryption works','<p>Argon2id derives a wrapping key from your passphrase, using a random salt and 64 MiB of memory. It protects a random 256-bit vault master key. Each item has a separate random key wrapped by that master key.</p><p>Contents use Tink’s AES-GCM-HKDF streaming encryption with AES-256-GCM. The index and key wrappers use authenticated AES-GCM; thumbnails are encrypted using keys derived from item keys. Authenticated encryption detects tampering and truncation.</p><p>Changing a passphrase rewraps the same vault key. It does not change old backups or stop someone with an old secret and old vault files deriving that key from those copies.</p>'),
('On-device storage and network access','<p>The current 0.4.2 app declares no INTERNET permission, has no account or ads, and uses no developer server. Android cloud backup and device-transfer backup are disabled for its data.</p><p>A provider you choose in Android’s document picker can upload a backup under its own terms. A readable export is outside the vault’s protection. Opening a website uses your browser’s network access.</p><p>These statements describe the current app. Before a future billing release, the privacy information and store disclosures will need to reflect that release’s behaviour.</p>'),
('Unlock methods','<p>Your passphrase and recovery key remain the root secrets. Optional biometric unlock uses Android’s strong-biometric authentication and a Keystore-wrapped key. Phone screen-lock and in-app pattern unlock are also available on supported devices; release builds require hardware protection for those methods.</p><p>Anyone who knows your phone’s PIN, pattern or password can open NullKey if phone screen-lock unlock is enabled. An in-app pattern is weaker than a passphrase or biometric authentication. Five wrong patterns disable that method; your passphrase still works.</p><p>Screen-lock and pattern unlock pause after an app update or seven days without typing the passphrase. Restoring a backup turns all optional unlock methods off until you enable them again.</p>'),
('Recovery and backups','<p>A recovery key opens existing encrypted data. A backup preserves a separate copy. After losing a phone, you need both the backup and a passphrase or recovery key valid for it.</p><p>Backup verification rereads the archive, authenticates the index, every encrypted item segment and every thumbnail, and matches the current vault snapshot. Restoring also authenticates the contents before installing them. A restore requires an empty vault and does not overwrite an existing one.</p><p>Practise with sample data and check restored contents. Keep the secret for each backup separately: changing today’s credentials does not update older backups. Alvento cannot recreate missing files or recover lost secrets.</p>'),
('Originals and device limits','<p>Imports keep originals by default. Optional original removal verifies eligible local copies first. Supported photos and videos require Android’s confirmation to move to trash; supported documents can be deleted permanently. Cloud and other-app copies can remain, and sync can propagate deletions.</p><p>A compromised phone, keyboard or accessibility service can expose information you type or display. File counts, approximate sizes, thumbnail presence and filesystem times are not hidden. Replacing files with an older copy of the same vault is not detected.</p><p>Release builds block ordinary screenshots; debug builds permit captures for interface review. Deleting files is not guaranteed secure erasure. Readable exports, clipboard history and other copies need separate attention.</p>'),
('What has been checked','<p>NullKey is in internal testing. The 0.4.2 candidate passed 124 JVM tests in the app’s release checks, and the updated icon and back-exit behaviour were checked on a Samsung S23 Ultra. These checks are not an independent security audit or proof of compatibility with every phone.</p><p>This website describes the 0.4.2 implementation and release documents reviewed on 29 October 2026. It does not claim that the full device test suite was rerun for that version.</p><p><a href="'+PRIVACY+'">Read the app privacy policy</a>.</p>')]
page('/security/','Security, recovery & device limits','How NullKey encrypts your files, protects keys and checks backups, with clear limits for optional unlock methods and compromised devices.',article('Your keys.<br>Clear boundaries.','Understand what the current app protects, what it leaves on your device and what recovery depends on.',security))
for i,(slug,title,description,sections) in enumerate(guides):
    body=article(esc(title),esc(description),[(esc(h),'<p>'+esc(p)+'</p>') for h,p in sections], 'Practical privacy guide')
    body+='<div class="notice">NullKey is in internal testing. Keep a separate, tested backup of irreplaceable files. '+a('/availability/','See availability')+'.</div><p class="note">Reviewed 29 October 2026 · '+a('/guides/','All guides')+'</p>'
    page('/guides/'+slug+'/',title,description,body)
page('/guides/','Android privacy & backup guides','Practical guides to encrypted vaults, private documents, original photos, recovery keys and offline backups.',head('Practical privacy','A little understanding.<br>A better routine.','Start with the question you have. Keep track of your copies and know how you would recover them.')+'<div class="guide-grid section">'+guides_cards(guides)+'</div>')
about=[('Made by Alvento','<p>NullKey is an Android product by <a href="https://alvento.uk">Alvento Ltd</a>, a UK company, number 16394298. We build the app around on-device encryption and secrets you hold.</p>'),('Contact and support','<p>Email <a href="mailto:hello@alvento.uk?subject=NullKey%20support">hello@alvento.uk</a> with “NullKey” in the subject. For a problem with the app, tell us the app version, Android version and the steps that led to it.</p><p>Do not send passphrases, recovery keys, backups or private vault contents. Use sample data if you need to describe a problem. For a security issue, use the subject “NullKey security”.</p>'),('App and website privacy','<p>The offline app and this website are separate systems. <a href="'+PRIVACY+'">Read NullKey’s published app privacy policy</a> for the vault, unlock methods, imports, backups and support correspondence.</p><p>This product website has no signup form, file upload, tracking analytics or advertising scripts. This product section is hosted with Alvento’s main website. Hosting services may process request and operational information to serve pages. Visiting a website still makes network requests, even though the app itself works offline.</p><p><a href="https://alvento.uk/privacy/">Alvento’s website privacy notice</a> describes the company website and contact services.</p>')]
page('/about/','About NullKey & support','NullKey is made by Alvento Ltd. Find product support, security contact details and the published app privacy policy.',article('A named company.<br>A direct way to reach us.','NullKey by Alvento. Built around private files that stay with you.',about,'About / contact'))
# Install only generated product files; the existing app privacy page is preserved.
for source in OUT.rglob('*'):
    if source.is_file():
        target = ROOT.parents[1] / 'nullkey' / source.relative_to(OUT)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, target)
print(f'Built {len(routes)} integrated NullKey pages; existing privacy policy preserved')
